import{_ as s,C as r,o,c as l,ag as t,E as n}from"./chunks/framework.CtWPcAmt.js";const y=JSON.parse('{"title":"Payment Management","description":"","frontmatter":{},"headers":[],"relativePath":"payments/payment-management.md","filePath":"payments/payment-management.md","lastUpdated":1786088921000}'),i={name:"payments/payment-management.md"};function m(d,e,g,p,c,u){const a=r("ImagePopup");return o(),l("div",null,[e[0]||(e[0]=t('<h1 id="payment-management" tabindex="-1">Payment Management <a class="header-anchor" href="#payment-management" aria-label="Permalink to &quot;Payment Management&quot;">​</a></h1><p>Payment Management is how sellers get paid for what they&#39;ve sold. A seller requests payment for their fulfilled orders, and the admin settles it from a central <strong>Seller Payout Management</strong> view that tracks what&#39;s owed, what&#39;s been paid, and what&#39;s still outstanding.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How a seller requests payment for an order</li><li>How the admin reviews and pays sellers</li><li>What the payout view and transactions ledger track</li></ul></div><h2 id="requesting-payment-seller" tabindex="-1">Requesting payment (seller) <a class="header-anchor" href="#requesting-payment-seller" aria-label="Permalink to &quot;Requesting payment (seller)&quot;">​</a></h2><p>After a seller has <strong>invoiced</strong> and <strong>completed</strong> an order, they can <strong>Request Payment</strong> for it from <strong>Sales → Orders</strong>. The request covers the seller&#39;s earning on the order — the invoiced total minus <a href="/payments/commission-management">commission</a> — and the button only appears when there&#39;s actually a remaining amount to pay and the order hasn&#39;t already been requested, paid, or refunded. Submitting sets the order&#39;s <strong>seller payment status</strong> to <em>requested</em> and notifies the admin.</p><h2 id="paying-sellers-admin" tabindex="-1">Paying sellers (admin) <a class="header-anchor" href="#paying-sellers-admin" aria-label="Permalink to &quot;Paying sellers (admin)&quot;">​</a></h2><p>The admin manages every request under <strong>Marketplace → Sales → Payment Requests</strong> — the <strong>Seller Payout Management</strong> screen. Four summary cards give the whole picture at a glance:</p>',7)),n(a,{src:"/images/payment-management/payout-management.png",alt:"Admin Seller Payout Management"}),e[1]||(e[1]=t('<ul><li><strong>Payable Orders</strong> — how many orders are awaiting payout.</li><li><strong>Unpaid Payout Amount</strong> — the total still owed to sellers.</li><li><strong>Total Commission Earned</strong> — commission on orders already paid out.</li><li><strong>Unpaid Sellers</strong> — how many sellers are still owed, out of the total.</li></ul><p>The grid lists each payable order with its gross amount, <strong>remaining total</strong>, <strong>seller total invoiced</strong>, the <strong>seller / shop</strong>, and <strong>total paid</strong>. Select <strong>Pay Now</strong> on a row, add a <strong>comment</strong> (for example, a bank-transfer reference), and confirm — the payment is recorded, the remaining balance updates, and the order flips to <strong>paid</strong> once fully settled.</p><h2 id="transactions" tabindex="-1">Transactions <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;Transactions&quot;">​</a></h2><p>Every settlement is logged under <strong>Marketplace → Sales → Transactions</strong>, giving a full payment history — the seller, transaction ID, comment, and amount — with a detailed view per transaction that breaks the payment down by item (total, commission, seller total).</p>',4)),n(a,{src:"/images/payment-management/transactions.png",alt:"Marketplace transactions"}),e[2]||(e[2]=t('<p>A seller sees their own side under <strong>Sales → Transactions</strong>, and can print a transaction as a PDF.</p><div class="info custom-block"><p class="custom-block-title">Payout statuses</p><p>An order&#39;s payout moves through <strong>pending → requested → paid</strong>; a refunded order shows <strong>refunded</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">Settle many at once</p><p>To pay several sellers or orders together, use the bulk action on this screen — see <a href="/payments/mass-payout-management">Mass Payout Management</a>.</p></div>',3))])}const _=s(i,[["render",m]]);export{y as __pageData,_ as default};
